import sys

def main():
    with open('/workdir/data/input.txt', 'r') as f:
        grid = [list(line.strip()) for line in f if line.strip()]

    rows, cols = len(grid), len(grid[0])

    x_cells = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 'X']
    n = len(x_cells)

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for i in range(n):
        r, c = x_cells[i]
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 'X':
                for j in range(n):
                    if x_cells[j] == (nr, nc):
                        adj[i].append(j)
                        break

    # Lexicographic ordering by row then column
    def lexicographic_order(cell1, cell2):
        r1, c1 = cell1
        r2, c2 = cell2
        if r1 != r2:
            return r1 < r2
        return c1 < c2

    unique_paths = set()

    # Use bitmask for visited
    def dfs(node, visited, path):
        if len(path) == n:
            start = path[0]
            end = path[-1]
            if lexicographic_order(start, end):
                unique_paths.add(tuple(path))
            return

        for neighbor in adj[node]:
            if not (visited & (1 << neighbor)):
                visited |= (1 << neighbor)
                path.append(x_cells[neighbor])
                dfs(neighbor, visited, path)
                path.pop()
                visited &= ~(1 << neighbor)

    for start_idx in range(n):
        visited = 1 << start_idx
        path = [x_cells[start_idx]]
        dfs(start_idx, visited, path)

    print(len(unique_paths))

if __name__ == "__main__":
    main()
